/* ===== v2 customer: home bits, explore, profile, product, saved ===== */
UI.exTab='p';UI.exF={p:null,b:null,s:null};UI.isub='';
const exDef=tab=>tab==='p'?{ids:null,offerId:'',pmin:'',pmax:'',rating:0,cat:'',sub:'',brand:'',offers:false,instock:false,deliver:false,pickup:false,dist:0,featured:false,sort:'relevance'}:tab==='b'?{cat:'',dist:0,rating:0,open:false,deliver:false,offers:false,verified:false,featured:false,sort:'relevance'}:{cats:[],subs:[],dist:0,rating:0,avail:false,offers:false,enq:false,pmin:'',pmax:'',verified:false,sort:'relevance'};
['p','b','s'].forEach(k=>UI.exF[k]=exDef(k));
const secBtn=(title,label,tab,pre)=>`<div class="sec"><h2>${t(title)}</h2><button class="btn t sm" data-act="exGo" data-tab="${tab}" data-pre='${esc(JSON.stringify(pre||{}))}'>${t(label)} ${ic('cr',16)}</button></div>`;
A.exGo=el=>{const tab=el.dataset.tab;UI.exTab=tab;UI.exF[tab]={...exDef(tab),...JSON.parse(el.dataset.pre||'{}')};UI.view='list';UI.sel='';go('explore')};
function initLazy(){const els=$$('[data-lazy]:not(.ld)');if(!els.length)return;if(!('IntersectionObserver' in window)){els.forEach(e=>e.classList.add('ld'));return}const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){const n=e.target;setTimeout(()=>n.classList.add('ld'),S.demo.slow?700:120);io.unobserve(n)}}),{rootMargin:'200px'});els.forEach(e=>io.observe(e))}
const shopCard=b=>{const d=dist(b),isS=b.id[0]==='s';return `<article class="card hover shopcard"><a class="cover" data-lazy href="#${isS?'svc':'biz'}-${b.id}" aria-label="${esc(nm(b.name))}">${art(b.emoji,b.hue,'f')}</a><div class="body"><div class="t bold truncate" style="font-size:1rem">${esc(nm(b.name))}</div><div class="small t2 truncate">${esc(catName(b.cat))} · ${esc(areaName(b.area))}</div><div class="meta small">${stars(b.rating)}<b>${b.rating.toFixed(1)}</b><span class="muted">(${b.rc})</span><span>·</span><span>${d.toFixed(1)} km</span></div><div class="row wrap-r" style="gap:6px">${openBadge(b)}${delivBadge(b)}</div><div class="acts"><a class="btn g" href="${telH(b.phone)}" aria-label="${t('Call')} ${esc(nm(b.name))}">${ic('phone',16)} ${t('Call')}</a><a class="btn p" href="#${isS?'svc':'biz'}-${b.id}">${t('View')}</a></div></div></article>`};
/* ---------- EXPLORE ---------- */
const pRating=p=>{const r=D().reviews.filter(x=>x.tid===p.id&&x.status==='published');return r.length?r.reduce((a,x)=>a+x.rating,0)/r.length:(biz(p.bid)||{rating:0}).rating};
const hasOffer=p=>offerPrice(p)<p.price||D().offers.some(o=>o.bid===p.bid&&o.status==='active'&&(!o.pids.length||o.pids.includes(p.id)));
const minFrom=x=>{const f=(x.services||[]).map(s=>s.from).filter(v=>v>0);return f.length?Math.min(...f):0};
function exProducts(){const f=UI.exF.p;let l=D().products.filter(p=>p.status==='active'&&biz(p.bid)&&biz(p.bid).status==='approved');
 if(f.ids)l=l.filter(p=>f.ids.includes(p.id));if(f.cat)l=l.filter(p=>p.cat===f.cat);if(f.sub)l=l.filter(p=>p.sub===f.sub);if(f.brand)l=l.filter(p=>brandOf(p)===f.brand);if(f.pmin!=='')l=l.filter(p=>offerPrice(p)>=+f.pmin);if(f.pmax!=='')l=l.filter(p=>offerPrice(p)<=+f.pmax);if(f.rating)l=l.filter(p=>pRating(p)>=f.rating);if(f.offers)l=l.filter(hasOffer);if(f.instock)l=l.filter(p=>p.avail&&p.stock>0);if(f.deliver)l=l.filter(p=>delivInfo(biz(p.bid)).ok);if(f.pickup)l=l.filter(p=>biz(p.bid).del.pickup);if(f.dist)l=l.filter(p=>dist(biz(p.bid))<=f.dist);if(f.featured)l=l.filter(p=>p.featured);
 const so=f.sort;if(so==='plow')l.sort((a,b)=>offerPrice(a)-offerPrice(b));else if(so==='phigh')l.sort((a,b)=>offerPrice(b)-offerPrice(a));else if(so==='rating')l.sort((a,b)=>pRating(b)-pRating(a));else if(so==='newest')l.sort((a,b)=>(+b.id.slice(1))-(+a.id.slice(1)));else l.sort((a,b)=>(b.featured-a.featured)||dist(biz(a.bid))-dist(biz(b.bid)));return l}
function exShops(){const f=UI.exF.b;let l=D().biz.filter(b=>b.status==='approved');if(f.cat)l=l.filter(b=>b.cat===f.cat);if(f.dist)l=l.filter(b=>dist(b)<=f.dist);if(f.rating)l=l.filter(b=>b.rating>=f.rating);if(f.open)l=l.filter(b=>openState(b).open);if(f.deliver)l=l.filter(b=>delivInfo(b).ok);if(f.offers){const ob=new Set(D().offers.filter(o=>o.status==='active').map(o=>o.bid));l=l.filter(b=>ob.has(b.id))}if(f.verified)l=l.filter(b=>b.verified);if(f.featured)l=l.filter(b=>b.featured);
 const so=f.sort;if(so==='rating')l.sort((a,b)=>b.rating-a.rating);else if(so==='newest')l.sort((a,b)=>(b.since||0)-(a.since||0));else l.sort((a,b)=>dist(a)-dist(b));return l}
function exServices(){const f=UI.exF.s;let l=[...D().svc,...D().biz.filter(b=>(b.services||[]).length)].filter(x=>x.status==='approved'&&(x.services||[]).length);if(f.cat)l=l.filter(x=>x.cat===f.cat);if(f.dist)l=l.filter(x=>dist(x)<=f.dist);if(f.rating)l=l.filter(x=>x.rating>=f.rating);if(f.avail)l=l.filter(x=>openState(x).open);if(f.verified)l=l.filter(x=>x.verified);if(f.pmin!=='')l=l.filter(x=>minFrom(x)>=+f.pmin);if(f.pmax!=='')l=l.filter(x=>minFrom(x)<=+f.pmax);
 const so=f.sort;if(so==='rating')l.sort((a,b)=>b.rating-a.rating);else if(so==='distance')l.sort((a,b)=>dist(a)-dist(b));else l.sort((a,b)=>(!!b.featured-!!a.featured)||dist(a)-dist(b));return l}
const exList=()=>UI.exTab==='p'?exProducts():UI.exTab==='b'?exShops():exServices();
const SORTS={p:[['relevance','Relevance'],['plow','Price: low to high'],['phigh','Price: high to low'],['rating','Rating'],['newest','Newest']],b:[['relevance','Relevance'],['distance','Distance'],['rating','Rating'],['newest','Newest']],s:[['relevance','Relevance'],['distance','Distance'],['rating','Rating'],['price','Price: low to high']]};
const DISTS=[[0,'Any distance'],[1,'Within 1 km'],[3,'Within 3 km'],[5,'Within 5 km'],[10,'Within 10 km']];
const RATS=[[0,'Any rating'],[3,'3★ & up'],[4,'4★ & up']];
const fsel=(k,l,v,opts)=>`<div class="field"><label for="x_${k}">${t(l)}</label><select class="input" id="x_${k}" data-chg="exf" data-k="${k}">${opts.map(o=>`<option value="${esc(o[0])}" ${String(o[0])===String(v)?'selected':''}>${esc(t(o[1]))}</option>`).join('')}</select></div>`;
const fchk=(k,l,v)=>`<label class="check"><input type="checkbox" ${v?'checked':''} data-chg="exf" data-k="${k}" style="accent-color:var(--primary)">${t(l)}</label>`;
function filterForm(tab){const f=UI.exF[tab];let h='';
 if(tab==='p'){const brands=[...new Set(D().products.filter(p=>!f.cat||p.cat===f.cat).map(brandOf))].sort();
  h=`<div class="fgroup"><h4>${t('Price')}</h4><div class="grid g2"><div class="field"><label for="x_pmin">${t('Min (₹)')}</label><input class="input" id="x_pmin" type="number" min="0" inputmode="numeric" value="${esc(f.pmin)}" data-in="exfi" data-k="pmin"></div><div class="field"><label for="x_pmax">${t('Max (₹)')}</label><input class="input" id="x_pmax" type="number" min="0" inputmode="numeric" value="${esc(f.pmax)}" data-in="exfi" data-k="pmax"></div></div><input type="range" min="0" max="100000" step="500" value="${f.pmax===''?100000:Math.min(100000,+f.pmax)}" data-in="exfi" data-k="pmaxr" aria-label="${t('Max price')}" style="width:100%;accent-color:var(--primary)"><div class="xs muted">${t('Up to')} ${inr(f.pmax===''?100000:+f.pmax)}${f.pmax===''?'+':''}</div></div>
  <div class="fgroup">${fsel('rating','Rating & reviews',f.rating,RATS)}</div><div class="fgroup">${fsel('cat','Category',f.cat,[['','All categories'],...D().cats.map(c=>[c.id,nm(c)]),...D().scats.map(c=>[c.id,nm(c)])])}${fsel('sub','Subcategory',f.sub,[['','All subcategories'],...(f.cat?subsFor(f.cat):allSubs()).map(x=>[x,x])])}${fsel('brand','Brand',f.brand,[['','All brands'],...brands.map(x=>[x,x])])}</div>
  <div class="fgroup"><h4>${t('Offers & availability')}</h4>${fchk('offers','Discount / offers',f.offers)}${fchk('instock','In stock only',f.instock)}${fchk('featured','Featured',f.featured)}</div><div class="fgroup"><h4>${t('Delivery or pickup')}</h4>${fchk('deliver','Delivers to my address',f.deliver)}${fchk('pickup','Self-pickup available',f.pickup)}${fsel('dist','Distance',f.dist,DISTS)}</div><div class="fgroup">${fsel('sort','Sort by',f.sort,SORTS.p)}</div>`}
 if(tab==='b')h=`<div class="fgroup">${fsel('cat','Category',f.cat,[['','All categories'],...D().cats.map(c=>[c.id,nm(c)])])}${fsel('dist','Distance / radius',f.dist,DISTS)}${fsel('rating','Rating',f.rating,RATS)}</div><div class="fgroup">${fchk('open','Open now',f.open)}${fchk('deliver','Delivers to my address',f.deliver)}${fchk('offers','Has offers',f.offers)}${fchk('verified','Verified',f.verified)}${fchk('featured','Featured',f.featured)}</div><div class="fgroup">${fsel('sort','Sort by',f.sort,SORTS.b)}</div>`;
 if(tab==='s')h=`<div class="fgroup">${svcSubFilter('ex',{cats:true})}</div><div class="fgroup">${fsel('dist','Distance',f.dist,DISTS)}${fsel('rating','Rating',f.rating,RATS)}</div><div class="fgroup"><h4>${t('Starts from (₹)')}</h4><div class="grid g2"><div class="field"><label for="x_pmin">${t('Min (₹)')}</label><input class="input" id="x_pmin" type="number" min="0" value="${esc(f.pmin)}" data-in="exfi" data-k="pmin"></div><div class="field"><label for="x_pmax">${t('Max (₹)')}</label><input class="input" id="x_pmax" type="number" min="0" value="${esc(f.pmax)}" data-in="exfi" data-k="pmax"></div></div></div><div class="fgroup">${fchk('avail','Available today (open now)',f.avail)}${fchk('offers','Has offers',f.offers)}${fchk('enq','Price on enquiry',f.enq)}${fchk('verified','Verified providers',f.verified)}</div><div class="fgroup">${fsel('sort','Sort by',f.sort,SORTS.s)}</div>`;
 return `<div class="exfm" data-tab="${tab}"><div class="row between"><h3>${t('Filters')}</h3><button class="btn t sm" data-act="exReset">${t('Reset')}</button></div>${h}</div>`}
const fLabel={cat:'Category',sub:'Subcategory',brand:'Brand',rating:'Rating',dist:'Distance',offers:'Offers',instock:'In stock',featured:'Featured',deliver:'Delivers to me',pickup:'Pickup',open:'Open now',verified:'Verified',avail:'Available now'};
function activeChips(){const f=UI.exF[UI.exTab],d=exDef(UI.exTab),out=[];Object.keys(f).forEach(k=>{if(Array.isArray(f[k])||k==='offerId'||k==='ids')return;if(k==='sort'){if(f.sort!==d.sort&&f.sort!=='relevance')out.push([k,t('Sort')+': '+t((SORTS[UI.exTab].find(x=>x[0]===f.sort)||[0,f.sort])[1])]);return}if(f[k]===d[k])return;let v=f[k];if(k==='pmin')out.push([k,t('Min')+' '+inr(v)]);else if(k==='pmax')out.push([k,t('Max')+' '+inr(v)]);else if(k==='cat')out.push([k,catName(v)]);else if(k==='rating')out.push([k,v+'★ & up']);else if(k==='dist')out.push([k,t('Within')+' '+v+' km']);else if(typeof v==='boolean')out.push([k,t(fLabel[k]||k)]);else out.push([k,t(fLabel[k]||k)+': '+v])});if(UI.exTab==='p'&&f.ids)out.push(['ids',t('Offer')+': '+((D().offers.find(o=>o.id===f.offerId)||{}).title||f.ids.length+' '+t('products'))]);if(UI.exTab==='s'){f.cats.forEach(c=>out.push(['cat:'+c,catName(c)]));f.subs.forEach(x=>out.push(['sub:'+x,subLabel(x)]))}return out}
function exResHtml(){const tab=UI.exTab,l=exList(),chips=activeChips();
 const head=`<div class="row between wrap-r"><b class="excnt" aria-live="polite">${l.length} ${t(tab==='p'?'products':tab==='b'?'shops':'services')}</b>${chips.length?`<button class="btn t sm" data-act="exReset">${t('Clear all')}</button>`:''}<button class="btn t sm" data-act="exCopy">${ic('copy',14)} ${t('Copy link')}</button></div>${chips.length?`<div class="row wrap-r" style="gap:6px">${chips.map(([k,lb])=>`<button class="rchip" data-act="exRm" data-k="${k}" aria-label="${t('Remove filter')}: ${esc(lb)}">${esc(lb)} <b>${ic('x',14)}</b></button>`).join('')}</div>`:''}`;
 let body;if(UI.view==='map'){const pins=tab==='p'?[...new Map(l.map(p=>[p.bid,ent(p.bid)])).values()]:tab==='s'?[...new Map(l.map(x=>[x.oid,x.owner])).values()]:l;body=`<div style="position:relative">${mapSvg('exmap',pins,{radius:UI.radius,sel:UI.sel})}${(()=>{const sel=pins.find(x=>x.id===UI.sel);return sel?`<div class="mapcard card pad row"><div class="mini art" style="--h:${sel.hue}">${sel.emoji}</div><div class="grow"><b>${esc(nm(sel.name))}</b><div class="small t2">${dist(sel).toFixed(1)} km · ${esc(areaName(sel.area))}</div></div><a class="btn p sm" href="#${sel.id[0]==='s'?'svc':'biz'}-${sel.id}">${t('View')}</a><a class="btn g sm" target="_blank" rel="noopener" href="${mapsDir(sel)}">${ic('nav',16)}</a></div>`:''})()}</div>`}else body='';
 const cards=l.length?`<div class="${tab==='p'?'grid auto-s':tab==='b'?'shopgrid':'grid auto'}">${l.map(x=>tab==='p'?prodCard(x):tab==='b'?shopCard(x):serviceCard(x)).join('')}</div>`:exEmpty(tab);
 return head+body+(UI.view==='list'||tab?cards:'')}
V.explore=()=>{const tab=UI.exTab,n=activeChips().length,cnts=exCounts();post.push(initLazy);post.push(exSync);
 return `<div class="stack"><div class="row between wrap-r"><h1>${t('Explore nearby')}</h1><div class="row"><button class="chip ${UI.view==='list'?'on':''}" data-act="exview" data-v="list">${ic('list',16)} ${t('List')}</button><button class="chip ${UI.view==='map'?'on':''}" data-act="exview" data-v="map">${ic('map',16)} ${t('Map')}</button></div></div>
 ${exCatPill()}<div class="tabs" role="tablist">${[['p','Products'],['b','Shops'],['s','Services']].map(([k,l])=>`<button role="tab" aria-selected="${tab===k}" class="${tab===k?'on':''}" data-act="extab" data-v="${k}">${t(l)} <span class="cnt tc" data-t="${k}" style="${tab===k?'':'background:var(--surface-2);color:var(--text)'}">${cnts[k]}</span></button>`).join('')}</div>
 ${alertBox('info',`<b>${t('Nearby')}</b> = ${t('how far it is from')} ${esc(S.loc.name)}. <b>${t('Delivers to you')}</b> = ${t('it delivers to your selected address.')}`)}
 <div class="exlay"><aside class="exside card pad" aria-label="${t('Filters')}">${filterForm(tab)}</aside><div class="stack"><button class="btn g exbtn" data-act="exFilters">${ic('filter',16)} ${t('Filters')}${n?` <span class="cnt">${n}</span>`:''}</button><div id="exres" class="stack">${exResHtml()}</div></div></div></div>`};
A.extab=el=>{UI.exTab=el.dataset.v;UI.sel='';render(true)};
function exRefresh(){exSync();sfRedrawAll();{const c=exCounts();$$('.tc').forEach(e=>e.textContent=c[e.dataset.t])}const r=$('#exres');if(r){r.innerHTML=exResHtml();initLazy()}$$('.exbtn').forEach(b=>{const n=activeChips().length;b.innerHTML=ic('filter',16)+' '+t('Filters')+(n?` <span class="cnt">${n}</span>`:'')});const sb=$('#exshow');if(sb)sb.textContent=t('Show')+' '+exList().length+' '+t('results')}
function exRerenderForms(){$$('.exfm').forEach(f=>{const keep=document.activeElement&&document.activeElement.id;f.outerHTML=filterForm(UI.exTab);if(keep){const e=document.getElementById(keep);e&&e.focus()}})}
CH.exf=el=>{const f=UI.exF[UI.exTab],k=el.dataset.k;f[k]=el.type==='checkbox'?el.checked:(k==='dist'||k==='rating')?+el.value:el.value;if(k==='cat'){f.sub='';f.brand=''}exRefresh();if(k==='cat')exRerenderForms()};
INP.exfi=(v,el)=>{const f=UI.exF[UI.exTab],k=el.dataset.k;if(k==='pmaxr'){f.pmax=+v>=100000?'':String(v);const m=$$('[data-k=pmax]');m.forEach(i=>i.value=f.pmax)}else f[k]=v;clearTimeout(UI.ext);UI.ext=setTimeout(exRefresh,150)};
A.exRm=el=>{const f=UI.exF[UI.exTab],d=exDef(UI.exTab),k=el.dataset.k;if(k.startsWith('cat:')){svcToggleCat(f,k.slice(4),false)}else if(k.startsWith('sub:')){f.subs=f.subs.filter(x=>x!==k.slice(4))}else if(k==='ids'){f.ids=null;f.offerId=''}else{f[k]=d[k];if(k==='cat')f.sub=''}render(true)};
A.exReset=()=>{UI.exF[UI.exTab]=exDef(UI.exTab);if($('#sheetRoot'))closeSheet();render(true)};
A.exFilters=()=>sheet(`<div class="row between"><b>${t(UI.exTab==='p'?'Product filters':UI.exTab==='b'?'Shop filters':'Service filters')}</b><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div>${filterForm(UI.exTab)}<button class="btn p block" id="exshow" data-act="exApply" style="margin-top:12px">${t('Show')} ${exList().length} ${t('results')}</button>`,{label:'Filters'});
A.exApply=()=>{closeSheet();render(true)};
/* ---------- UNIFIED PROFILE ---------- */
const itemsOf=x=>({p:D().products.filter(p=>p.bid===x.id&&p.status==='active'),s:x.services||[]});
const isOwnerView=id=>(S.role==='vendor'&&S.vend.bid===id)||(S.role==='provider'&&S.prov.sid===id);
function tagItem(tid){if(/-sv\d+$/.test(tid)){const o=ent(tid.split('-')[0]);const s=o&&(o.services||[]).find(x=>x.id===tid);return s?{k:'s',id:tid,name:s.n,price:s.p,owner:o}:null}const p=prod(tid);return p?{k:'p',id:tid,p,name:nm(p.name),price:inr(offerPrice(p)),owner:biz(p.bid)}:null}
function tagCards(m){const items=(m.tags||[]).map(tagItem).filter(Boolean);if(!items.length)return '';return `<div class="tagrow"><div class="lbl small">${t('In this video')}: ${items.map(i=>`<button class="chip" style="min-height:34px" data-act="tagOpen" data-id="${i.id}">${esc(i.name)}</button>`).join(' ')}</div><div class="grid g2">${items.map(i=>i.k==='p'?`<div class="card pad stack" style="gap:6px"><div class="row">${art(i.p.emoji,i.p.hue,'mini')}<div class="grow"><b class="small">${esc(i.name)}</b><div class="small">${i.price}</div></div></div><div class="row"><button class="btn p sm grow" data-act="tagCart" data-id="${i.id}">${ic('cart',14)} ${t('Add to cart')}</button><a class="btn g sm" href="#prod-${i.id}" data-act="closeSheet">${t('View')}</a></div></div>`:`<div class="card pad stack" style="gap:6px"><b class="small">${ic('wrench',14)} ${esc(i.name)}</b><div class="small t2">${esc(i.price)}</div><button class="btn o sm" data-act="tagOpen" data-id="${i.id}">${t('View service')}</button></div>`).join('')}</div></div>`}
A.tagOpen=el=>{const i=tagItem(el.dataset.id);if(!i)return;closeSheet();if(i.k==='p')go('prod-'+i.id);else{UI.btab='items';UI.isub='s';go((i.owner.id[0]==='s'?'svc-':'biz-')+i.owner.id)}};
A.tagCart=el=>{if(addToCart(el.dataset.id,1)){toast(t('Added to cart'),'cart');render(true)}};
function playerSheet(ownerId,mid){const o=ent(ownerId),m=(o.media||[]).find(x=>x.id===mid);if(!m)return;const hid=`vd|${ownerId}|${mid}`;
 sheet(`<div class="row between"><b class="truncate">${esc(m.title)}</b><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><div class="vcard" style="margin-top:10px"><div id="plr" class="art w" style="--h:${m.t==='yt'?0:330};border-radius:var(--r-md);position:relative"><span>${m.t==='yt'?'▶️':'📷'}</span><button class="btn p" style="position:absolute;bottom:12px;left:12px" data-act="plrGo" data-o="${ownerId}" data-m="${mid}">${ic('play',16)} ${t('Play')} (${mLabel(m)})</button></div><div class="row between wrap-r"><span class="badge info">${mKind(m)==='reel'?t('Reel'):t('Video')} · ${mLabel(m)}</span><div class="row">${heartBtn(hid,{kind:mKind(m),owner:ownerId,mid,title:m.title})}<a class="btn g sm" target="_blank" rel="noopener" href="${esc(extUrl(m))}">${t('Open in')} ${mLabel(m)}</a></div></div>${tagCards(m)}</div>`,{wide:true,label:m.title})}
A.playMedia=el=>playerSheet(el.dataset.o,el.dataset.m);
